from collections import Counter, deque

def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            if (r,c) in seen: continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); comp=[]
            while q:
                y,x=q.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<h and 0<=nx<w and (ny,nx) not in seen and grid[ny][nx]==color:
                        seen.add((ny,nx));q.append((ny,nx))
            comps.append((color,comp))
    out=[row[:] for row in grid]
    for color,comp in comps:
        if len(comp)!=1: continue
        r,c=comp[0]; counts=Counter()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x=r+dr,c+dc
            if 0<=y<h and 0<=x<w: counts[grid[y][x]]+=1
        if counts:
            m=max(counts.values()); choices=[col for col,n in counts.items() if n==m]
            # tie rule: if background-ish likely more local? use order first? 
            out[r][c]=choices[0]
