from collections import Counter, deque

def rect_transform(grid, threshold=0.8):
    h,w=len(grid),len(grid[0])
    base=Counter(v for row in grid for v in row).most_common(1)[0][0]
    out=[[base]*w for _ in range(h)]
    seen=set()
    for r0 in range(h):
      for c0 in range(w):
        color=grid[r0][c0]
        if color==base or (r0,c0) in seen: continue
        q=[(r0,c0)]; seen.add((r0,c0)); comp=[]
        while q:
          r,c=q.pop(); comp.append((r,c))
          for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x=r+dr,c+dc
            if 0<=y<h and 0<=x<w and (y,x) not in seen and grid[y][x]==color:
              seen.add((y,x)); q.append((y,x))
        avail=set(comp)
        while avail:
          rmin=min(r for r,c in avail); rmax=max(r for r,c in avail)
          cmin=min(c for r,c in avail); cmax=max(c for r,c in avail)
          hh=rmax-rmin+1; ww=cmax-cmin+1
          pref=[[0]*(ww+1) for _ in range(hh+1)]
          for r,c in avail: pref[r-rmin+1][c-cmin+1]=1
          for i in range(1,hh+1):
            for j in range(1,ww+1): pref[i][j]+=pref[i-1][j]+pref[i][j-1]-pref[i-1][j-1]
          best=None
          for top in range(hh):
            for bot in range(top+1,hh):
              for left in range(ww):
                for right in range(left+1,ww):
                  area=(bot-top+1)*(right-left+1)
                  n=pref[bot+1][right+1]-pref[top][right+1]-pref[bot+1][left]+pref[top][left]
                  if n/area>=threshold:
                    score=(area,n/area)
                    if best is None or score>best[0]: best=(score,top,bot,left,right)
          if best is None: break
          _,top,bot,left,right=best
          cells={(rmin+i,cmin+j) for i in range(top,bot+1) for j in range(left,right+1)}
          for r,c in cells: out[r][c]=color
          # Remove all source cells belonging to this selected rectangle, plus anomalous cells enclosed by it.
          avail-=cells
          # If candidate was full-density, any leftover cells become separate candidate(s).
          if not cells: break
    return out

